/**
 * KnockoutJS Template Binding Error Debugger
 * 
 * Provides enhanced error messages for binding failures,
 * including suggested property names based on Levenshtein distance.
 */

/**
 * Calculate the Levenshtein distance between two strings.
 * @param {string} str1
 * @param {string} str2
 * @returns {number} The edit distance
 */
function levenshteinDistance(str1, str2) {
    const m = str1.length;
    const n = str2.length;

    // Create a 2D array for dynamic programming
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    // Base cases
    for (let i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for (let j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    // Fill the DP table
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const cost = str1[i - 1] === str2[j - 1] ? 0 : 1;
            dp[i][j] = Math.min(
                dp[i - 1][j] + 1,      // deletion
                dp[i][j - 1] + 1,      // insertion
                dp[i - 1][j - 1] + cost // substitution
            );
        }
    }

    return dp[m][n];
}

/**
 * Create a debug helper for a given ViewModel.
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} A debug helper with diagnostic methods
 */
function createDebugHelper(viewModel) {
    // Extract and sort available properties
    const availableProperties = Object.keys(viewModel).sort();

    return {
        /**
         * Diagnose a missing property binding error.
         * @param {string} propertyName - The name of the property that failed to bind
         * @returns {Object} Diagnostic information
         */
        diagnoseMissingProperty(propertyName) {
            const missingProperty = propertyName;

            // Find the best matching property using Levenshtein distance
            let bestDist = Infinity;
            let bestMatch = null;

            for (const prop of availableProperties) {
                const dist = levenshteinDistance(missingProperty, prop);
                if (dist < bestDist || (dist === bestDist && prop < bestMatch)) {
                    bestDist = dist;
                    bestMatch = prop;
                }
            }

            // Only suggest if distance is 3 or less
            const suggestion = (bestDist <= 3) ? bestMatch : null;

            return {
                error: true,
                missingProperty: missingProperty,
                availableProperties: availableProperties,
                suggestion: suggestion
            };
        }
    };
}

module.exports = {
    createDebugHelper,
    levenshteinDistance
};
EOF"}

